import sys
from collections import deque

INF = 10**9
MAXN = 15
MAXT = 65

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    t = int(next(it))

    grid1 = [[''] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        row = next(it)
        for j in range(1, n + 1):
            grid1[i][j] = row[j - 1]

    # assign node ids
    node_id = [[[0] * (n + 1) for _ in range(n + 1)] for _ in range(t + 2)]
    id_counter = 1
    for time in range(t + 2):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                node_id[time][i][j] = id_counter
                id_counter += 1

    source = 0
    sink = id_counter
    id_counter += 1

    grid2 = [[''] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        row = next(it)
        for j in range(1, n + 1):
            grid2[i][j] = row[j - 1]

    # BFS from all 'Z' cells
    dist = [[-1] * (n + 1) for _ in range(n + 1)]
    q = deque()
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if grid1[i][j] == 'Z':
                q.append((i, j))
                dist[i][j] = 0

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    while q:
        uy, ux = q.popleft()
        for dy, dx in dirs:
            vy, vx = uy + dy, ux + dx
            if 1 <= vy <= n and 1 <= vx <= n and grid1[vy][vx] != 'Y' and dist[vy][vx] == -1:
                dist[vy][vx] = dist[uy][ux] + 1
                q.append((vy, vx))

    # cap distances
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if dist[i][j] == -1 or dist[i][j] > t:
                dist[i][j] = INF

    # Dinic implementation
    class Dinic:
        def __init__(self, N: int):
            self.N = N
            self.E = []  # list of edges
            self.g = [[] for _ in range(N)]  # adjacency list of edge indices
            self.d = [0] * N
            self.pt = [0] * N

        def add_edge(self, u: int, v: int, cap: int) -> None:
            if u == v:
                return
            self.E.append([u, v, cap, 0])  # [u, v, cap, flow]
            self.g[u].append(len(self.E) - 1)
            self.E.append([v, u, 0, 0])
            self.g[v].append(len(self.E) - 1)

        def bfs(self, S: int, T: int) -> bool:
            self.d = [self.N + 1] * self.N
            self.d[S] = 0
            q = deque([S])
            while q:
                u = q.popleft()
                if u == T:
                    break
                for idx in self.g[u]:
                    e = self.E[idx]
                    if e[3] < e[2] and self.d[e[1]] > self.d[e[0]] + 1:
                        self.d[e[1]] = self.d[e[0]] + 1
                        q.append(e[1])
            return self.d[T] != self.N + 1

        def dfs(self, u: int, T: int, flow: int = -1) -> int:
            if u == T or flow == 0:
                return flow
            for i in range(self.pt[u], len(self.g[u])):
                self.pt[u] = i
                idx = self.g[u][i]
                e = self.E[idx]
                oe = self.E[idx ^ 1]
                if self.d[e[1]] == self.d[e[0]] + 1:
                    amt = e[2] - e[3]
                    if flow != -1 and amt > flow:
                        amt = flow
                    pushed = self.dfs(e[1], T, amt)
                    if pushed:
                        e[3] += pushed
                        oe[3] -= pushed
                        return pushed
            return 0

        def max_flow(self, S: int, T: int) -> int:
            total = 0
            while self.bfs(S, T):
                self.pt = [0] * self.N
                while True:
                    flow = self.dfs(S, T)
                    if not flow:
                        break
                    total += flow
            return total

    dinic = Dinic(id_counter)

    # source edges
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if '1' <= grid1[i][j] <= '9':
                dinic.add_edge(source, node_id[0][i][j], ord(grid1[i][j]) - ord('0'))

    # time edges
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if grid1[i][j] == 'Y' or grid1[i][j] == 'Z':
                continue
            for dy, dx in dirs:
                vy, vx = i + dy, j + dx
                if 1 <= vy <= n and 1 <= vx <= n and grid1[vy][vx] != 'Y' and grid1[vy][vx] != 'Z':
                    for x in range(t):
                        if dist[vy][vx] >= x + 1 and dist[i][j] > x:
                            dinic.add_edge(node_id[x][i][j], node_id[x + 1][vy][vx], 1000)

    # sink edges (two steps combined)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if grid1[i][j] == 'Y' or grid1[i][j] == 'Z':
                continue
            if '1' <= grid2[i][j] <= '9':
                cap = ord(grid2[i][j]) - ord('0')
                for x in range(t + 1):
                    dinic.add_edge(node_id[x][i][j], node_id[t + 1][i][j], cap)
                dinic.add_edge(node_id[t + 1][i][j], sink, cap)

    print(dinic.max_flow(source, sink))

if __name__ == "__main__":
    solve()
